using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class CandidateComparisonPage:UserControl{TextBox ids;DataGridView grid;public CandidateComparisonPage(){BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=65,Padding=new Padding(4)};ids=Ui.Text();ids.Width=330;ids.Text="1,2";var run=Ui.Button(L.Fa?"مقایسه":"Compare");run.Click+=(s,e)=>LoadData();top.Controls.Add(Ui.Label(L.Fa?"شناسه‌ها (مثال 1,2,3)":"Candidate IDs (e.g. 1,2,3)"));top.Controls.Add(ids);top.Controls.Add(run);grid=Ui.Grid();Controls.Add(grid);Controls.Add(top);grid.BringToFront();}void LoadData(){var parts=ids.Text.Split(',');var valid=new System.Collections.Generic.List<int>();foreach(var x in parts){int n;if(int.TryParse(x.Trim(),out n))valid.Add(n);}if(valid.Count<2){MessageBox.Show(L.Fa?"حداقل دو شناسه معتبر وارد کنید":"Enter at least two valid IDs");return;}var ps=new System.Collections.Generic.List<SqlParameter>();var names=new System.Collections.Generic.List<string>();for(int i=0;i<valid.Count;i++){names.Add("@p"+i);ps.Add(new SqlParameter("@p"+i,valid[i]));}string sql="SELECT c.Id,c.FullName,c.City,c.Education,c.PrimarySkill,c.ExperienceYears,c.Status,COUNT(a.Id) Applications,ISNULL(MAX(a.Score),0) BestScore,COUNT(DISTINCT s.Id) SkillCount FROM Candidates c LEFT JOIN Applications a ON a.CandidateId=c.Id LEFT JOIN CandidateSkills s ON s.CandidateId=c.Id WHERE c.Id IN ("+string.Join(",",names)+") GROUP BY c.Id,c.FullName,c.City,c.Education,c.PrimarySkill,c.ExperienceYears,c.Status ORDER BY BestScore DESC,c.ExperienceYears DESC";grid.DataSource=Database.Query(sql,ps.ToArray());}}}